import{_ as t,o,c as s,a0 as r}from"./chunks/framework.DQOulFGV.js";const m=JSON.parse('{"title":"1. Executive Summary & Design Principles","description":"","frontmatter":{},"headers":[],"relativePath":"01-executive-summary.md","filePath":"01-executive-summary.md"}'),a={name:"01-executive-summary.md"};function i(n,e,d,c,l,u){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="_1-executive-summary-design-principles" tabindex="-1">1. Executive Summary &amp; Design Principles <a class="header-anchor" href="#_1-executive-summary-design-principles" aria-label="Permalink to &quot;1. Executive Summary &amp; Design Principles&quot;">​</a></h1><blockquote><p>Normative. This document defines <em>why</em> Momus-MCP exists and the constraints every later design decision must respect.</p></blockquote><h2 id="_1-0-naming" tabindex="-1">1.0 Naming <a class="header-anchor" href="#_1-0-naming" aria-label="Permalink to &quot;1.0 Naming&quot;">​</a></h2><p><strong>Momus</strong> (Μῶμος) is the ancient Greek spirit and personification of <strong>satire, mockery, blame, and harsh criticism</strong> — the one deity whose entire office was to find fault, and who was cast out of Olympus for doing it too well. His name literally translates to <strong>&quot;blame&quot;</strong> or <strong>&quot;censure&quot;</strong>.</p><p>The name is deliberate and doubly apt:</p><ul><li>Momus is the <strong>ultimate critic among the deities</strong>, and this project is an <em>unsparing fault-finder</em> for test suites — see principle P5 (<em>unsparing but fair</em>).</li><li>Momus is the god of <strong>mockery</strong>, and the subject of this tool is <strong>mock objects</strong> — the test doubles that stand in for production code.</li></ul><h2 id="_1-1-vision" tabindex="-1">1.1 Vision <a class="header-anchor" href="#_1-1-vision" aria-label="Permalink to &quot;1.1 Vision&quot;">​</a></h2><p>Coding agents routinely declare tasks finished on the strength of tests that cannot fail in the ways that matter. Momus-MCP gives agents and developers a <strong>deterministic, local-first static auditor</strong> that answers one question about any test suite:</p><blockquote><p><strong>&quot;If this test suite passes, what has actually been proven about the production code?&quot;</strong></p></blockquote><p>Momus-MCP is positioned as the <em>test-integrity counterpart</em> to linters and type checkers: where ESLint enforces style and <code>tsc</code> enforces types, Momus enforces <strong>the contract between a test double and the production code it stands in for</strong>. It is not a coverage tool (that asks &quot;was this line executed?&quot;) and not a mutation tester (that asks &quot;would a fault fail this test?&quot;). It asks a cheaper, earlier question: <em>&quot;could this test fail at all, for the right reason?&quot;</em></p><h3 id="_1-1-1-positioning-statement" tabindex="-1">1.1.1 Positioning statement <a class="header-anchor" href="#_1-1-1-positioning-statement" aria-label="Permalink to &quot;1.1.1 Positioning statement&quot;">​</a></h3><blockquote><p>Momus-MCP is the unsparing fault-finder for test doubles: it statically verifies that mocks match their production contracts, detects assertions that cannot fail, and surfaces drift before code is committed — local-first, deterministic, and token-efficient.</p></blockquote><h3 id="_1-1-2-non-goals-explicit" tabindex="-1">1.1.2 Non-goals (explicit) <a class="header-anchor" href="#_1-1-2-non-goals-explicit" aria-label="Permalink to &quot;1.1.2 Non-goals (explicit)&quot;">​</a></h3><ul><li><strong>Not a test runner.</strong> Momus never executes tests. All analysis is static (AST-level).</li><li><strong>Not a coverage tool.</strong> No instrumentation, no runtime hooks.</li><li><strong>Not a mutation tester.</strong> No code rewriting or execution.</li><li><strong>Not a mocking library.</strong> It analyzes mocks; it does not provide them.</li><li><strong>Not a network service.</strong> No cloud component, no telemetry, no phone-home.</li><li><strong>Not a dynamic analyzer.</strong> Data-flow analysis is intra-procedural and conservative; it may miss cases that require runtime information (documented limitations in §3.7 of <code>03-analysis-algorithms.md</code>).</li></ul><h2 id="_1-2-the-problem-false-green-test-suites" tabindex="-1">1.2 The problem: false-green test suites <a class="header-anchor" href="#_1-2-the-problem-false-green-test-suites" aria-label="Permalink to &quot;1.2 The problem: false-green test suites&quot;">​</a></h2><h3 id="_1-2-1-failure-modes" tabindex="-1">1.2.1 Failure modes <a class="header-anchor" href="#_1-2-1-failure-modes" aria-label="Permalink to &quot;1.2.1 Failure modes&quot;">​</a></h3><p>When coding agents encounter failing tests, the observed failure modes are:</p><ol><li><strong>Over-mocking</strong> — dependencies are stubbed out so aggressively that the buggy path being fixed is itself replaced by a stub. The test then passes because the bug is no longer reachable.</li><li><strong>Tautological assertions</strong> — assertions that re-assert mock wiring instead of business outcomes: <code>expect(mock.getTotal()).toBe(42)</code> where <code>mock.getTotal</code> was configured with <code>mockReturnValue(42)</code> a line earlier.</li><li><strong>Mock drift</strong> — test doubles return shapes, types, or signatures that no longer match the production AST definitions. Tests pass against a fictional version of the API.</li><li><strong>Zero-reach mocks</strong> — stubs and spies that are configured or asserted but never influence any observable outcome (the SUT never calls them; no assertion consumes them).</li></ol><p>Each failure mode produces the same observable symptom: <strong>green suite, unproven code</strong>.</p><h3 id="_1-2-2-why-static-analysis-is-the-right-tool" tabindex="-1">1.2.2 Why static analysis is the right tool <a class="header-anchor" href="#_1-2-2-why-static-analysis-is-the-right-tool" aria-label="Permalink to &quot;1.2.2 Why static analysis is the right tool&quot;">​</a></h3><ul><li>Tests and their mocks are <strong>code artifacts</strong>; contract violations are statically visible in most cases (missing methods, wrong arity, mismatched shapes).</li><li>Static analysis is <strong>deterministic and fast</strong> — no test execution, no flakiness, no network.</li><li>Static analysis can run <strong>in the agent&#39;s editing loop</strong> (MCP tools) and <strong>in CI/pre-commit</strong> with identical results, because results depend only on file contents.</li></ul><h2 id="_1-3-design-principles" tabindex="-1">1.3 Design principles <a class="header-anchor" href="#_1-3-design-principles" aria-label="Permalink to &quot;1.3 Design principles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Principle</th><th>Consequence</th></tr></thead><tbody><tr><td>P1</td><td><strong>Local-first</strong></td><td>Everything runs in-process on the user&#39;s machine. No accounts, no servers, no egress. The MCP server speaks <code>stdio</code> by default; <code>--transport http</code> (Streamable HTTP) is an explicit opt-in for remote use.</td></tr><tr><td>P2</td><td><strong>Deterministic</strong></td><td>Identical workspace state ⇒ identical output. No randomness, no timestamps in output, no dependence on ambient environment beyond the files themselves. Rule order, issue order, and IDs are stable.</td></tr><tr><td>P3</td><td><strong>Token-efficient</strong></td><td>Every issue renders in <strong>&lt; 100 tokens</strong>; tool descriptions are written to fit prompt budgets; reports cap at a configurable number of issues (<code>maxIssuesPerReport</code>, default 50). See <code>05-output-format.md</code>.</td></tr><tr><td>P4</td><td><strong>Zero framework boot</strong></td><td>Analysis is pure static parsing. Momus never imports, evaluates, or executes the user&#39;s modules or test frameworks. No <code>jest</code>/<code>vitest</code>/<code>phpunit</code> bootstrap, no <code>ts-node</code>, no project module loading. This is also a security boundary (§1.5).</td></tr><tr><td>P5</td><td><strong>Unsparing but fair</strong></td><td>Rules are precise and conservative: they must have <strong>near-zero false positives</strong> on clean code (target &lt; 1% on the clean corpus, §3.6 of <code>03-analysis-algorithms.md</code>). Uncertainty is reported as <code>info</code>, not <code>error</code>.</td></tr><tr><td>P6</td><td><strong>Auditable exemptions</strong></td><td>Suppressions are explicit, visible comments/config — never silent heuristics. Every suppressed finding can be listed with <code>momus rules --show-suppressed</code>.</td></tr><tr><td>P7</td><td><strong>Extensible by design</strong></td><td>Language support is a plugin interface (<code>LanguageParser</code>), rules are composable units (<code>Rule</code>), output is a pure formatter over a stable <code>Issue</code> model.</td></tr><tr><td>P8</td><td><strong>Read-only by default</strong></td><td>All MCP tools are <code>readOnlyHint: true</code>, <code>destructiveHint: false</code>. Nothing writes outside <code>.momus</code> cache unless a future mutation tool is explicitly approved (see §1.5).</td></tr><tr><td>P9</td><td><strong>Dogfooded</strong></td><td>The Momus repository runs Momus on itself in CI. Zero findings allowed.</td></tr><tr><td>P10</td><td><strong>Fail loudly, fail locally</strong></td><td>Parse errors and unresolvable imports are reported as structured diagnostics (<code>severity: &quot;error&quot;</code>, rule <code>SYS-001</code>), never silently skipped.</td></tr></tbody></table><h2 id="_1-4-scope" tabindex="-1">1.4 Scope <a class="header-anchor" href="#_1-4-scope" aria-label="Permalink to &quot;1.4 Scope&quot;">​</a></h2><h3 id="_1-4-1-supported-languages-and-frameworks-matrix" tabindex="-1">1.4.1 Supported languages and frameworks (matrix) <a class="header-anchor" href="#_1-4-1-supported-languages-and-frameworks-matrix" aria-label="Permalink to &quot;1.4.1 Supported languages and frameworks (matrix)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Phase</th><th>Language</th><th>Test frameworks</th><th>Mocking patterns detected</th></tr></thead><tbody><tr><td>1</td><td>TypeScript / JavaScript</td><td>Vitest, Jest</td><td><code>vi.mock</code>, <code>vi.spyOn</code>, <code>vi.fn</code>, <code>jest.mock</code>, <code>jest.spyOn</code>, <code>jest.fn</code>, <code>jest.requireMock</code>, <code>vi.mocked</code>, manual object-literal and <code>Proxy</code>-based doubles</td></tr><tr><td>2</td><td>PHP</td><td>PHPUnit, Pest</td><td><code>createMock</code>, <code>createStub</code>, <code>createConfiguredMock</code>, <code>createPartialMock</code>, <code>getMockBuilder</code>, <code>getMockForAbstractClass</code>, Mockery (<code>Mockery::mock</code>/<code>spy</code>, <code>shouldReceive</code>), Pest <code>mock()</code>/<code>spy()</code> helpers, anonymous-class stubs</td></tr><tr><td>3+ (extensible)</td><td>Rust, Python, Go (candidate, via new <code>LanguageParser</code> plugins)</td><td>—</td><td>—</td></tr></tbody></table><p><strong>Framework detection:</strong> per-file, by import surface (<code>vitest</code>, <code>@jest/globals</code>, <code>PHPUnit\\Framework\\TestCase</code>, Pest functions). A file may declare multiple frameworks; rules apply per-detected framework.</p><h3 id="_1-4-2-supported-test-styles-phase-1" tabindex="-1">1.4.2 Supported test styles (Phase 1) <a class="header-anchor" href="#_1-4-2-supported-test-styles-phase-1" aria-label="Permalink to &quot;1.4.2 Supported test styles (Phase 1)&quot;">​</a></h3><ul><li><code>*.test.ts</code>, <code>*.spec.ts</code>, <code>*.test.tsx</code>, <code>*.spec.tsx</code>, <code>*.test.js</code>, <code>*.spec.js</code>, <code>*.test.mjs</code></li><li>Test files located under any directory matching <code>**/__tests__/**</code>, or named with the above suffixes.</li><li>Configurable via <code>.momusrc</code> <code>testFilePatterns</code> (defaults above).</li></ul><h2 id="_1-5-threat-model-hard-constraints" tabindex="-1">1.5 Threat model &amp; hard constraints <a class="header-anchor" href="#_1-5-threat-model-hard-constraints" aria-label="Permalink to &quot;1.5 Threat model &amp; hard constraints&quot;">​</a></h2><p>Momus-MCP parses <strong>untrusted workspace code</strong> (the user&#39;s project) inside its own process. Threat model:</p><table tabindex="0"><thead><tr><th>Threat</th><th>Mitigation</th></tr></thead><tbody><tr><td>Malicious/accidental code execution during parse</td><td>Parsers are <strong>pure AST builders</strong>: TypeScript compiler API and <code>php-parser</code> do not evaluate code. Momus never <code>import()</code>s project modules, never calls <code>require</code>, never spawns the project&#39;s toolchain. Enforced by an import-statement lint rule in the Momus codebase (no dynamic require of project paths outside the parser sandbox).</td></tr><tr><td>Data exfiltration</td><td><strong>No network APIs</strong> in the runtime path. All tools are pure functions of the workspace. The only network-touching code is the optional Streamable HTTP transport, which serves the same read-only tools.</td></tr><tr><td>Destructive writes</td><td>All MCP tools are read-only (<code>destructiveHint: false</code>). The CLI&#39;s future <code>--fix</code> / <code>momus apply</code> mode (Phase 3) <strong>must</strong> (a) print a full diff, (b) require <code>--yes</code>, and (c) refuse to run when <code>CI=true</code> without <code>--yes</code>. Default: no writes at all.</td></tr><tr><td>Resource exhaustion (huge files, symlink loops)</td><td>File discovery honors <code>.gitignore</code>; maximum file size (default 2 MB) and maximum workspace size (default 500k LOC indexed per run) with explicit <code>SYS-002</code> warnings; symlink loops are pruned.</td></tr><tr><td>Cache poisoning</td><td>The <code>.momus</code> cache is keyed by content hash (<code>sha256</code> of file bytes); any content change invalidates the entry. Cache is advisory only — results are always recomputable.</td></tr><tr><td>Prompt-injection via code comments</td><td>Suppression directives are <strong>syntactically strict</strong> (regex-validated, e.g. <code>@momus-ignore(?:[:=][A-Z0-9-]+)?</code>) and only suppress specific rules/spans — never arbitrary text. They cannot alter tool behavior beyond scoped suppression.</td></tr></tbody></table><p><strong>Zero-destructive-writes rule (canonical):</strong> <em>Momus must never modify a user file without an explicit, interactive confirmation of the exact diff.</em> In the MCP surface this is trivially satisfied: all tools are read-only. In the CLI, <code>apply</code>/<code>--fix</code> is gated as above.</p><h2 id="_1-6-success-metrics" tabindex="-1">1.6 Success metrics <a class="header-anchor" href="#_1-6-success-metrics" aria-label="Permalink to &quot;1.6 Success metrics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Target</th><th>Measured by</th></tr></thead><tbody><tr><td>False-positive rate on clean code</td><td>&lt; 1% of clean-corpus files report any issue</td><td>Clean corpus in <code>test/fixtures/clean/**</code> must yield 0 issues</td></tr><tr><td>Precision on anti-pattern gallery</td><td>100% of planted violations detected in Phase 1 corpus</td><td><code>test/fixtures/gallery/**</code> golden outputs</td></tr><tr><td>Single-file audit latency</td><td>&lt; 200 ms (cold, first run)</td><td>benchmark suite (<code>bench/</code>)</td></tr><tr><td>Workspace index (10k LOC)</td><td>&lt; 1 s cold, &lt; 100 ms incremental</td><td>benchmark suite</td></tr><tr><td>Issue rendering</td><td>&lt; 100 tokens per issue (mean ≈ 30)</td><td><code>tokens</code> field assertion in golden tests</td></tr><tr><td>Zero self-findings</td><td>CI fails if <code>momus audit .</code> reports any issue on the Momus repo</td><td>CI job <code>self-audit</code></td></tr></tbody></table><h2 id="_1-7-license-distribution" tabindex="-1">1.7 License &amp; distribution <a class="header-anchor" href="#_1-7-license-distribution" aria-label="Permalink to &quot;1.7 License &amp; distribution&quot;">​</a></h2><ul><li>MIT license, source-available from day one.</li><li>Distribution: npm packages (<code>@momus/core</code>, <code>@momus/mcp-server</code>, <code>@momus/cli</code>, <code>@momus/parser-typescript</code>, <code>@momus/parser-php</code>), GitHub Action (<code>momus-mcp/action</code>), and public MCP registry listings (Phase 4).</li></ul><hr><p><strong>Next:</strong> <a href="./02-architecture.html"><code>02-architecture.md</code></a> — parsing strategy, IR, symbol index, mock identification.</p>',39)])])}const p=t(a,[["render",i]]);export{m as __pageData,p as default};
